//! Oracle vectors: `mb_substr` with positive, negative and extreme offsets (including the
//! `ValueError`s), `mb_str_split` with every kind of length, mbstring's UTF-8 character length
//! table, `mb_ord`, and `mb_convert_case` mode validation.
//!
//! `tests/vectors/substr_split.json` is generated by `tests/vectors/substr_split.gen.php` in the
//! PHP oracle (`research/php-oracle`); its header describes the format. Regenerate from the
//! repository root with
//!
//! ```text
//! docker run --rm -i twig-oracle:3.31.1 php < crates/twig-unicode/tests/vectors/substr_split.gen.php \
//!     > crates/twig-unicode/tests/vectors/substr_split.json
//! ```

use serde::Deserialize;
use serde_json::Value;
use twig_unicode::{ValueError, mb_convert_case, mb_ord, mb_str_split, mb_substr, utf8};

#[derive(Deserialize)]
struct Vectors {
    php_version: String,
    substr: Vec<SubstrGroup>,
    split: Split,
    mblen: Vec<usize>,
    ord: Vec<(String, Value)>,
    convert_case_modes: Vec<(i64, String)>,
}

#[derive(Deserialize)]
struct SubstrGroup {
    strings: Vec<String>,
    starts: Vec<i64>,
    lengths: Vec<Option<i64>>,
    results: Vec<Vec<Vec<String>>>,
}

#[derive(Deserialize)]
struct Split {
    strings: Vec<String>,
    lengths: Vec<i64>,
    results: Vec<Vec<Value>>,
}

fn load() -> Vectors {
    let vectors: Vectors = serde_json::from_str(include_str!("vectors/substr_split.json")).unwrap();
    assert_eq!(vectors.php_version, "8.5.13");
    vectors
}

fn hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

/// The vector notation: hex of the result, or `!` and the `ValueError` message.
fn notation(result: Result<Vec<u8>, ValueError>) -> String {
    match result {
        Ok(bytes) => bytes.iter().map(|b| format!("{b:02x}")).collect(),
        Err(err) => format!("!{}", err.message()),
    }
}

#[test]
fn substr_matches_php() {
    let vectors = load();
    let mut count = 0;
    for group in &vectors.substr {
        for (s, per_string) in group.strings.iter().zip(&group.results) {
            let s = hex(s);
            for (&start, per_start) in group.starts.iter().zip(per_string) {
                for (&length, want) in group.lengths.iter().zip(per_start) {
                    let got = notation(mb_substr(&s, start, length));
                    assert_eq!(&got, want, "mb_substr({s:02X?}, {start}, {length:?})");
                    count += 1;
                }
            }
        }
    }
    assert!(count > 4000, "{count}");
}

#[test]
fn str_split_matches_php() {
    let vectors = load();
    for (s, per_string) in vectors.split.strings.iter().zip(&vectors.split.results) {
        let s = hex(s);
        for (&length, want) in vectors.split.lengths.iter().zip(per_string) {
            let got = match mb_str_split(&s, length) {
                Ok(pieces) => Value::Array(
                    pieces
                        .iter()
                        .map(|p| Value::String(p.iter().map(|b| format!("{b:02x}")).collect()))
                        .collect(),
                ),
                Err(err) => Value::String(format!("!{}", err.message())),
            };
            assert_eq!(&got, want, "mb_str_split({s:02X?}, {length})");
        }
    }
}

#[test]
fn mblen_table_matches_php() {
    let vectors = load();
    assert_eq!(vectors.mblen.len(), 256);
    for (b, &want) in vectors.mblen.iter().enumerate() {
        assert_eq!(utf8::mblen(b as u8), want, "byte {b:#04x}");
    }
}

#[test]
fn ord_matches_php() {
    let vectors = load();
    for (s, want) in &vectors.ord {
        let got = match mb_ord(&hex(s)) {
            Ok(Some(cp)) => Value::from(cp),
            Ok(None) => Value::Bool(false),
            Err(err) => Value::String(format!("!{}", err.message())),
        };
        assert_eq!(&got, want, "mb_ord({s})");
    }
}

#[test]
fn convert_case_mode_validation_matches_php() {
    let vectors = load();
    for (mode, want) in &vectors.convert_case_modes {
        assert_eq!(
            &notation(mb_convert_case(b"aB", *mode)),
            want,
            "mode {mode}"
        );
    }
}
